"""Three LOG-owned words also needed by META; do not duplicate later."""
import json
from pathlib import Path
from lesson_authoring import entry as E
BASE=Path(__file__).resolve().parents[1];OUT=BASE/'.cache/batch200/drafts/rewrite_spec'
M=[['希腊 metéōros → tà metéōra','在高处的 → 高空中的现象'],['希腊 metéōra + -logía → meteōrología','对高空现象的论述；-logía 接 lógos“讲述、说明”']]
N=M+[['法语 météorologie／希腊学术词 → 英语 meteorology','大气现象的研究，后来形成现代气象学']]
W=[E('meteorology','英 /ˌmiːtiəˈrɒlədʒi/；美 /ˌmiːtiəˈrɑːlədʒi/','气象学；气象现象','研究头顶这层空气怎样流动、成云、降雨，并据此理解和预测天气。','希腊 metéōra“高空现象” + -logía“论述、研究”；英语有法语及希腊学术借入路线，不能只拿今天 meteor“流星”的意思拼出“流星学”。',N,'古代高空现象的范围很宽，包含风雨等，并不像今天日常 meteor 那样主要指流星。现代气象学关注大气及其过程；天气预报是重要应用，不是这门学科的全部。','study meteorology；a degree in meteorology；applied meteorology。','astronomy 主要研究天体与宇宙；meteorology 主要研究大气。两个词都容易让人想到天空，研究对象却不同。',('She studied meteorology to understand how storms develop.','她学习气象学，是为了理解风暴怎样形成。'),('Meteorology combines observations with physical models of the atmosphere.','气象学把观测与大气物理模型结合起来。'),sources=['https://www.etymonline.com/word/meteorology','https://en.wiktionary.org/wiki/meteorology#English']),E('meteorologist','英 /ˌmiːtiəˈrɒlədʒɪst/；美 /ˌmiːtiəˈrɑːlədʒɪst/','气象学家；气象工作者','把天气观测、物理知识和模型连起来，研究大气变化的人。','meteorology + -ist，以 -ist 表示研究或从事该领域的人。',N+[['英语 meteorology + -ist → meteorologist','从事气象研究或专业气象工作的人']],'有人做预报，有人研究云、风暴或观测方法。并非每位电视天气播报员都有同样的专业背景，也不是每位 meteorologist 都出镜播天气。','a broadcast meteorologist；a research meteorologist；consult a meteorologist。','meteorologist 不是研究陨石的通用称呼；不要被现代 meteor 的常见义带偏。',('The meteorologist compared the radar image with surface observations.','气象工作者把雷达图像与地面观测作了比较。'),('A research meteorologist explained why the two forecasts differed.','一位气象研究者解释了两份预报为什么不同。'),sources=['https://en.wiktionary.org/wiki/meteorologist#English','https://www.etymonline.com/word/meteorologist']),E('meteorological','英 /ˌmiːtiərəˈlɒdʒɪkəl/；美 /ˌmiːtiərəˈlɑːdʒɪkəl/','气象的；气象学的','说明某项数据、仪器或条件是在描述大气和天气。','现代可对应 meteorology + -ical；历史上也有法语 météorologique 或希腊 meteōrologikos 拉丁化形式的形容词借入，不能一概当英语名词之后才派生。',M+[['希腊 meteōrologikós；经拉丁化形式或法语 météorologique → 英语 meteorological','关于大气现象的；独立形容词借入路线']],'meteorological data 包括温度、气压、风等观测；meteorological conditions 是当时气象状况。这个长词的重音落在 -log-，不是把 meteor 的重音原样保留下来。','meteorological data；meteorological conditions；a meteorological station。','meteorological 关注大气与天气；meteorological station 是气象站，不是专门监看流星的观测站。',('The station has collected meteorological data for more than fifty years.','这个站点收集气象数据已有五十多年。'),('Poor meteorological conditions delayed the balloon launch.','不利的气象条件推迟了气球放飞。'),sources=['https://www.etymonline.com/word/meteorological','https://www.etymonline.com/word/meteorology','https://en.wiktionary.org/wiki/meteorological#English'])]
for w in W:
 assert len(w['examples'])>=2 and all(len(n)==2 for n in w['history'])
(OUT/'words_batch200_spec_shared_meteorology.json').write_text(json.dumps(W,ensure_ascii=False,indent=2))
print(len(W),'words',sum(len(w['examples']) for w in W),'examples')
